 20	/**
 21	 * Registers workspace routes for the `/api/projects/:id/workspaces` resource
 22	 * group on the provided `Router` instance.
 23	 *
 24	 * All handlers delegate to the supplied `WorkspaceManager` and map results
 25	 * or errors to the appropriate HTTP status codes:
 26	 *
 27	 * | Method | Path                                                              | Success | Failure     |
 28	 * |--------|-------------------------------------------------------------------|---------|-------------|
 29	 * | GET    | /api/projects/:id/workspaces                                     | 200     | 404         |
 30	 * | POST   | /api/projects/:id/workspaces                                     | 201     | 400/404     |
 31	 * | GET    | /api/projects/:id/workspaces/:wid                                | 200     | 404         |
 32	 * | PUT    | /api/projects/:id/workspaces/:wid                                | 200     | 400/404     |
 33	 * | PUT    | /api/projects/:id/workspaces/:wid/rename                         | 200     | 400/404     |
 34	 * | DELETE | /api/projects/:id/workspaces/:wid                                | 204     | 404         |
 35	 * | POST   | /api/projects/:id/workspaces/:wid/setup                          | 200     | 400/404/500 |
 36	 * | GET    | /api/projects/:id/workspaces/:wid/health                         | 200     | 404         |
 37	 * | POST   | /api/projects/:id/workspaces/:wid/regenerate-workspace-file      | 200     | 400/404/500 |
 38	 * | POST   | /api/projects/:id/workspaces/:wid/launch/vscode                  | 200     | 400/404/500 |
 39	 * | POST   | /api/projects/:id/workspaces/:wid/launch/github-desktop/:rid     | 200     | 400/404/500 |
 40	 */
 41	export function registerWorkspaceRoutes(
 42	    router: Router,
 43	    workspaceManager: WorkspaceManager,
 44	    workspaceOrchestrator: WorkspaceOrchestrator,
 45	    appConfig: AppConfig,
 46	    projectManager: ProjectManager,
 47	    errorLogManager: ErrorLogManager,
 48	    /** Overrides the default `launchApplication` function — for testing only. */
 49	    launchFn: (command: string, args: string[]) => Promise<void> = launchApplication,
 50	): void {
 51	
 52	    // Helper: compute absolute workspace folder path.
 53	    function workspaceFolder(projectId: string, workspaceId: string): string {
 54	        return path.join(appConfig.projectsFolder, projectId, workspaceId);
 55	    }
 56	
 57	    // Helper: augment a WorkspaceInfo with an `Initialized` boolean and `FolderPath` string.
 58	    function withInitialized<T extends { ProjectID: string; WorkspaceID: string }>(ws: T): T & { Initialized: boolean; FolderPath: string } {
 59	        const wsFolder = workspaceFolder(ws.ProjectID, ws.WorkspaceID);
 60	        return { ...ws, Initialized: fs.existsSync(wsFolder), FolderPath: wsFolder };
 61	    }
