 63	    // ------------------------------------------------------------------
 64	    // GET /api/projects/:id/workspaces — list all workspaces
 65	    // ------------------------------------------------------------------
 66	    router.get('/api/projects/:id/workspaces', (
 67	        _req: IncomingMessage,
 68	        res: ServerResponse,
 69	        params: Record<string, string>,
 70	    ): void => {
