 45	// ---------------------------------------------------------------------------
 46	// Module-level state  (one server instance at a time)
 47	// ---------------------------------------------------------------------------
 48	//
 49	// Only a single HTTP server and a single PollingManager can be active per
 50	// Node.js process.  This is intentional for the CLI use case.
 51	//
 52	// **Test authors:** always call `await stopServer()` in an `afterEach` /
 53	// `afterAll` hook to release the port and reset these references before the
 54	// next test suite starts a fresh server.
 55	
 56	let _server: http.Server | null = null;
 57	let _pollingManager: PollingManager | null = null;
 58	
 59	// ---------------------------------------------------------------------------
 60	// Public API
 61	// ---------------------------------------------------------------------------
 62	
 63	/**
 64	 * Wires all server components together, starts listening, and kicks off the
 65	 * background polling loop.
 66	 *
 67	 * The returned promise resolves once the server is actually listening on the
 68	 * chosen port (i.e. after the `listening` event fires).
 69	 *
 70	 * If the port is already in use (`EADDRINUSE`), the promise rejects with a
 71	 * descriptive `Error` and an actionable log message is printed to stderr.
 72	 *
 73	 * Calling `startServer()` while a server is already running throws
 74	 * synchronously.
 75	 *
 76	 * Internally creates an `ErrorLogManager` shared across all subsystems
 77	 * (WorkspaceOrchestrator, BranchOrchestrator, PollingManager, and Router);
 78	 * no external reference is returned.
 79	 */
 80	export function startServer(config: ServerConfig): Promise<void> {
 81	    if (_server !== null) {
 82	        throw new Error('Server is already running. Call stopServer() first.');
 83	    }
 84	
 85	    const port = config.serverPort ?? config.appConfig.serverPort ?? 4200;
 86	    const pollInterval = config.pollIntervalSeconds ?? config.appConfig.gitPollingIntervalSeconds ?? 30;
 87	
 88	    // ------------------------------------------------------------------
 89	    // Instantiate managers & orchestrators
 90	    // ------------------------------------------------------------------
 91	    const repoManager = new RepositoryManager(config.appConfig);
 92	    const projectManager = new ProjectManager(config.appConfig, repoManager);
 93	    const workspaceManager = new WorkspaceManager(projectManager);
 94	    const errorLogManager = new ErrorLogManager(config.appConfig);
 95	    const workspaceOrchestrator = new WorkspaceOrchestrator(
 96	        config.appConfig,
 97	        projectManager,
 98	        workspaceManager,
 99	        repoManager,
100	        errorLogManager,

101	    );
102	    const branchOrchestrator = new BranchOrchestrator(
103	        config.appConfig,
104	        projectManager,
105	        workspaceManager,
106	        errorLogManager,
107	    );
108	    const pollingManager = new PollingManager(
109	        config.appConfig,
110	        projectManager,
111	        workspaceManager,
112	        undefined,       // fetchStatusFn — use the default real git layer
113	        errorLogManager,
114	    );
115	
116	    // ------------------------------------------------------------------
117	    // One-time migration: move .code-workspace files from flat layout to
118	    // per-project subdirectory layout (idempotent, safe to run every startup).
119	    // ------------------------------------------------------------------
120	    const projectSlugs = projectManager.list().map((p) => p.Id);
121	    const migratedCount = migrateWorkspaceFiles(config.appConfig.projectsFolder, projectSlugs);
122	    if (migratedCount > 0) {
123	        process.stdout.write(
124	            `[repo-parallelizer] Migrated ${migratedCount} workspace file(s) to per-project subdirectories.\n`,
125	        );
126	    }
127	
128	    // ------------------------------------------------------------------
129	    // Build the router and register all route groups
130	    // ------------------------------------------------------------------
131	    const router = new Router();
132	    router.setErrorLogManager(errorLogManager);
133	    registerRepositoryRoutes(router, repoManager);
134	    registerProjectRoutes(router, projectManager);
135	    registerWorkspaceRoutes(router, workspaceManager, workspaceOrchestrator, config.appConfig, projectManager, errorLogManager);
136	    registerBranchRoutes(router, branchOrchestrator, workspaceManager);
137	    registerStatusRoutes(router, pollingManager, projectManager, workspaceManager, config.appConfig);
138	    registerConfigRoutes({ router, appConfig: config.appConfig, pollingManager });
139	    registerErrorLogRoutes(router, errorLogManager);
140	
141	    // ------------------------------------------------------------------
142	    // Create HTTP server with the static-first request pipeline
143	    // ------------------------------------------------------------------
144	    const server = http.createServer((req: IncomingMessage, res: ServerResponse) => {
145	        // Static files are checked first; if the file exists it is served and
146	        // we return immediately without consulting the router.
147	        serveStatic(req, res, config.staticDir)
148	            .then((served) => {
149	                if (!served) {
150	                    // Not a static file — hand off to the API router.
151	                    // The router writes its own 404 when nothing matches.
152	                    router.handle(req, res);
153	                }
154	            })
155	            .catch(() => {
156	                // Should not happen (serveStatic only rejects on programmer
157	                // error), but guard anyway to avoid unhandled-rejection noise.
158	                sendError(res, 500, 'Internal server error.');
159	            });
160	    });
161	
162	    // ------------------------------------------------------------------
163	    // Return a promise that resolves on 'listening' and rejects on error
164	    // ------------------------------------------------------------------
165	    return new Promise<void>((resolve, reject) => {
166	        server.once('error', (err: NodeJS.ErrnoException) => {
167	            if (err.code === 'EADDRINUSE') {
168	                process.stderr.write(
169	                    `[repo-parallelizer] ERROR: Port ${port} is already in use.\n` +
170	                    `  Try a different port by setting "serverPort" in your config.json.\n`,
171	                );
172	            }
173	            reject(err);
174	        });
175	
176	        server.listen(port, '127.0.0.1', () => {
177	            // Store module-level references so stopServer() can reach them.
178	            _server = server;
179	            _pollingManager = pollingManager;
180	
181	            // Kick off the background git polling loop.
182	            pollingManager.start(pollInterval);
183	
184	            resolve();
185	        });
186	    });
187	}
